import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../../api/axios';

export default function AdminDashboard() {
  const queryClient = useQueryClient();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTopUpModalOpen, setIsTopUpModalOpen] = useState(false);
  const [selectedCard, setSelectedCard] = useState(null);
  const [pointsToAdd, setPointsToAdd] = useState('');
  const [topUpError, setTopUpError] = useState('');
  // Modal Form State
  const [rfidUid, setRfidUid] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [formError, setFormError] = useState('');

  // 1. Fetch Dashboard Data
  const { data, isLoading, isError } = useQuery({
    queryKey: ['adminDashboardData'],
    queryFn: async () => {
      const response = await api.get('/admin/dashboard');
      return response.data;
    }
  });
const topUpMutation = useMutation({
    mutationFn: async ({ cardId, points }) => {
      const response = await api.post(`/admin/cards/${cardId}/topup`, { pointsToAdd: points });
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries(['adminDashboardData']);
      setPointsToAdd('');
      setTopUpError('');
      setIsTopUpModalOpen(false);
      setSelectedCard(null);
    },
    onError: (error) => {
      setTopUpError(error.response?.data?.message || 'Failed to top up card.');
    }
  });

  const handleTopUp = (e) => {
    e.preventDefault();
    setTopUpError('');
    if (!pointsToAdd || pointsToAdd <= 0) {
      return setTopUpError('Please enter a valid point amount.');
    }
    topUpMutation.mutate({ cardId: selectedCard.id, points: pointsToAdd });
  };
  
  const openTopUpModal = (card) => {
    setSelectedCard(card);
    setIsTopUpModalOpen(true);
  };
  // 2. Setup the Mutation for Registering a Card
  const registerCardMutation = useMutation({
    mutationFn: async (newCardData) => {
      const response = await api.post('/admin/cards', newCardData);
      return response.data;
    },
    onSuccess: () => {
      // Magically refresh the dashboard table data!
      queryClient.invalidateQueries(['adminDashboardData']);
      
      // Reset form and close modal
      setRfidUid('');
      setUserEmail('');
      setFormError('');
      setIsModalOpen(false);
    },
    onError: (error) => {
      setFormError(error.response?.data?.message || 'Failed to register card.');
    }
  });

  const handleRegisterCard = (e) => {
    e.preventDefault();
    setFormError('');
    registerCardMutation.mutate({ rfidUid, userEmail });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-red-600 font-medium">Failed to load dashboard. Ensure you are logged in.</div>
      </div>
    );
  }

  const { stats, cards } = data;
  const displayStats = [
    { name: 'Active Cards', value: stats.activeCards },
    { name: 'Total Points Issued', value: stats.totalPointsIssued.toLocaleString() },
    { name: 'Current Rate', value: `1 Pt = ₦${stats.conversionRate}` },
  ];

  return (
    <div className="min-h-screen bg-gray-50 relative">
      <header className="bg-white shadow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Merchant Dashboard</h1>
            <p className="mt-1 text-sm text-gray-500">Manage your loyalty program and card assignments.</p>
          </div>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-indigo-600 text-white px-5 py-2.5 rounded-md hover:bg-indigo-700 transition shadow-sm font-medium"
          >
            + Register New Card
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Stats and Table code remains exactly the same */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          {displayStats.map((stat) => (
            <div key={stat.name} className="bg-white rounded-lg shadow-sm p-6 border border-gray-200">
              <p className="text-sm font-medium text-gray-500 truncate">{stat.name}</p>
              <p className="mt-2 text-3xl font-semibold text-indigo-600">{stat.value}</p>
            </div>
          ))}
        </div>

        <div className="bg-white shadow-sm rounded-lg border border-gray-200 overflow-hidden">
          <div className="px-6 py-5 border-b border-gray-200 flex justify-between items-center">
            <h3 className="text-lg leading-6 font-medium text-gray-900">Registered Loyalty Cards</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Card UID</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Customer</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Point Balance</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {cards.length === 0 ? (
                  <tr>
                    <td colSpan="4" className="px-6 py-8 text-center text-gray-500">No cards registered yet.</td>
                  </tr>
                ) : (
                  cards.map((card) => (
                    <tr key={card.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-mono text-gray-600">{card.uid}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 font-medium">{card.user}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{card.balance} pts</td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2.5 py-0.5 inline-flex text-xs leading-5 font-semibold rounded-full ${
                          card.status === 'Active' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                        }`}>
                          {card.status}
                        </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {/* 3. The Registration Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
          <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            
            {/* Background overlay */}
            <div className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity" onClick={() => setIsModalOpen(false)}></div>
            <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
            
            {/* Modal panel */}
            <div className="inline-block align-bottom bg-white rounded-lg text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-lg sm:w-full">
              <form onSubmit={handleRegisterCard}>
                <div className="bg-white px-4 pt-5 pb-4 sm:p-6 sm:pb-4">
                  <h3 className="text-lg leading-6 font-medium text-gray-900" id="modal-title">Register New RFID Card</h3>
                  
                  {formError && (
                    <div className="mt-3 bg-red-50 text-red-700 p-3 rounded text-sm">
                      {formError}
                    </div>
                  )}

                  <div className="mt-4 space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700">Card UID (Hex)</label>
                      <input 
                        type="text" 
                        required
                        value={rfidUid}
                        onChange={(e) => setRfidUid(e.target.value.toUpperCase())}
                        placeholder="e.g., A1B2C3D4"
                        className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm font-mono uppercase" 
                      />
                      <p className="mt-1 text-xs text-gray-500">Scan the card on your terminal to get this ID.</p>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">Customer Email (Optional)</label>
                      <input 
                        type="email" 
                        value={userEmail}
                        onChange={(e) => setUserEmail(e.target.value)}
                        placeholder="customer@email.com"
                        className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm" 
                      />
                      <p className="mt-1 text-xs text-gray-500">Leave blank to register an unassigned card.</p>
                    </div>
                  </div>
                </div>
                <div className="bg-gray-50 px-4 py-3 sm:px-6 sm:flex sm:flex-row-reverse">
                  <button 
                    type="submit" 
                    disabled={registerCardMutation.isLoading}
                    className="w-full inline-flex justify-center rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none sm:ml-3 sm:w-auto sm:text-sm disabled:opacity-50"
                  >
                    {registerCardMutation.isLoading ? 'Saving...' : 'Register Card'}
                  </button>
                  <button 
                    type="button" 
                    onClick={() => setIsModalOpen(false)}
                    className="mt-3 w-full inline-flex justify-center rounded-md border border-gray-300 shadow-sm px-4 py-2 bg-white text-base font-medium text-gray-700 hover:bg-gray-50 focus:outline-none sm:mt-0 sm:ml-3 sm:w-auto sm:text-sm"
                  >
                    Cancel
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
